//! The markdown client of the conformance runs (tests/markdown, docs/spec/protocol.md section 5). `run_case` runs each case
//! of tests/markdown/cases.json against a flowmark server (the test markdown_conformance), and `case_corpus` makes the corpus
//! of a case of the markdown suite of a recipe.
//! The model of tests/markdown/corpus/dbspec/conformance.dbs is generated by build.rs into this module's OUT_DIR.

#[allow(
    dead_code,
    unused_imports,
    clippy::all,
    reason = "the generated models are included whole, a crate uses only some of them, and lints of hand-written code do not apply to generated code"
)]
mod markdown_model {
    include!(concat!(env!("OUT_DIR"), "/markdown/orm_model.rs"));
}

use std::io::BufRead;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};

use crate::plain::Plain;
use markdown_model::{CodecRows, Logs, People, Tasks};
use polyspec_orm::{Config, Db, Error, Isolation, StyledValue};
use serde_json::{json, Value};

/// The directory of the shared suite: cases.json, flowmark.version, corpus/.
pub fn conformance_dir() -> PathBuf {
    polyspec_orm_testcase::manifest_dir().join("../../../tests/markdown")
}

/// The directory to delete. Dropping it deletes everything inside.
pub struct Scratch(pub PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        // A case that made its corpus read-only (the op database.read_only) leaves folders that the removal could not
        // empty: they take the permissions of the scratch folder, which the run created and no case changes.
        let scratch = std::fs::metadata(&self.0).map_err(|e| format!("stat {}: {e}", self.0.display()));
        if let Err(error) = scratch.and_then(|scratch| set_folders(&self.0, |_| scratch.permissions())) {
            eprintln!("{error}");
        }
        if let Err(error) = std::fs::remove_dir_all(&self.0) {
            eprintln!("remove {}: {error}", self.0.display());
        }
    }
}

/// Makes every folder under `root` one that the server may only read, through the read-only permission of the file system.
pub fn read_only_corpus(root: &Path) -> Result<(), String> {
    set_folders(root, |mut permissions| {
        permissions.set_readonly(true);
        permissions
    })
}

/// Sets the permissions of every folder under `root`, `root` included, to what `permissions` gives for its present ones.
fn set_folders(root: &Path, permissions: impl Fn(std::fs::Permissions) -> std::fs::Permissions) -> Result<(), String> {
    let mut folders = vec![root.to_path_buf()];
    while let Some(folder) = folders.pop() {
        let present = std::fs::metadata(&folder).map_err(|e| format!("stat {}: {e}", folder.display()))?.permissions();
        std::fs::set_permissions(&folder, permissions(present)).map_err(|e| format!("chmod {}: {e}", folder.display()))?;
        for entry in std::fs::read_dir(&folder).map_err(|e| format!("read {}: {e}", folder.display()))? {
            let entry = entry.map_err(|e| format!("read {}: {e}", folder.display()))?;
            if entry.file_type().map_err(|e| format!("stat {}: {e}", entry.path().display()))?.is_dir() {
                folders.push(entry.path());
            }
        }
    }
    Ok(())
}

/// The flowmark server the test started. Dropping it ends the process and waits for it.
pub struct Server(Child);

impl Drop for Server {
    fn drop(&mut self) {
        if let Err(error) = self.0.kill() {
            eprintln!("kill the server: {error}");
        }
        if let Err(error) = self.0.wait() {
            eprintln!("wait for the server: {error}");
        }
    }
}

/// The flowmark server the test started, and its corpus.
pub struct Served {
    bin: PathBuf,
    pub db: Db,
    dir: PathBuf,
    corpus: String,
    port: u16,
    token: String,
}

impl Served {
    fn dsn(&self, corpus: &str, token: &str) -> String {
        format!("markdown://127.0.0.1:{}/{corpus}?token={token}", self.port)
    }
}

/// The timestamp appended to the directory name so that names do not collide.
pub fn unique() -> u128 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()
}

/// The listener of one markdown.send step of the recipe helper: it accepts one connection, answers connect with
/// {"ok": true}, answers the setup statements of the SQLite dialect, such as the row lock table that a transaction needs, as
/// done, records the first other message, and answers that message and each later one with an error so that the call ends. `dsn` is the connection string of the connection to make; `first` yields the recorded message after the call.
pub struct SendListener {
    pub dsn: String,
    first: std::sync::mpsc::Receiver<Value>,
    thread: std::thread::JoinHandle<()>,
}

/// Starts the listener of one markdown.send step on a port of its own.
pub fn send_listener() -> SendListener {
    use std::io::Write;
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("a listener");
    let port = listener.local_addr().expect("its address").port();
    let (record, first) = std::sync::mpsc::channel();
    let thread = std::thread::spawn(move || {
        let Ok((conn, _)) = listener.accept() else { return };
        let mut writer = conn.try_clone().expect("a second handle");
        let mut lines = std::io::BufReader::new(conn).lines();
        let mut connected = false;
        let mut recorded = false;
        while let Some(Ok(line)) = lines.next() {
            let reply = if !std::mem::replace(&mut connected, true) {
                json!({ "ok": true })
            } else {
                let message: Value = match serde_json::from_str(&line) {
                    Ok(message) => message,
                    Err(error) => panic!("the markdown.send listener read a line that is not JSON: {error}"),
                };
                if message["op"] == "statement" && message["sql"].as_str().is_some_and(|sql| sql.starts_with("CREATE TABLE IF NOT EXISTS \"orm__")) {
                    json!({ "columns": [], "rows": [], "affected": 0, "last_insert_id": 0 })
                } else {
                    if !std::mem::replace(&mut recorded, true) {
                        // The receiver ends only with the case, after which nothing reads the record.
                        if record.send(message).is_err() {
                            return;
                        }
                    }
                    json!({ "error": { "code": "IR_INVALID", "message": "recorded by the markdown.send listener" } })
                }
            };
            if writer.write_all(format!("{reply}\n").as_bytes()).is_err() {
                return;
            }
        }
    });
    let token = "0123456789abcdef0123456789abcdef";
    SendListener { dsn: format!("markdown://127.0.0.1:{port}/conformance?token={token}"), first, thread }
}

impl SendListener {
    /// The first message the listener received, or none when the call sent no message. Call it after the call and the
    /// connection have ended: the call returns only after the listener has answered, so a sent message is already recorded.
    pub fn finish(self) -> Option<Value> {
        if let Err(panic) = self.thread.join() {
            std::panic::resume_unwind(panic);
        }
        // The listener has ended, so an empty channel is a call that sent no message.
        self.first.try_iter().next()
    }
}

/// Installs corpus/ as a new corpus, starts that server, and connects to it.
pub async fn serve(bin: &Path, scratch: &Path) -> (Served, Server) {
    let corpus = "conformance".to_owned();
    let dir = scratch.join(&corpus);
    std::fs::create_dir_all(dir.join("dbspec")).unwrap();
    std::fs::copy(conformance_dir().join("corpus/dbspec/conformance.dbs"), dir.join("dbspec/conformance.dbs")).unwrap();
    std::fs::copy(conformance_dir().join("corpus/dbspec/dbspec-set.json"), dir.join("dbspec/dbspec-set.json")).unwrap();
    polyspec_orm_testcase::step(format_args!("flowmark install {}", dir.display()));
    let install = Command::new(bin).arg("install").arg(&dir).output().unwrap();
    assert!(
        install.status.success(),
        "flowmark install: {}\n{}{}",
        install.status,
        String::from_utf8_lossy(&install.stdout),
        String::from_utf8_lossy(&install.stderr)
    );
    polyspec_orm_testcase::step(format_args!("flowmark serve {} --port 0", dir.display()));
    let mut child = Command::new(bin).arg("serve").arg(&dir).args(["--port", "0"]).stdout(Stdio::piped()).stderr(Stdio::inherit()).spawn().unwrap();
    let stdout = child.stdout.take().unwrap();
    let server = Server(child);
    let mut line = String::new();
    std::io::BufReader::new(stdout).read_line(&mut line).unwrap();
    let port = line
        .trim_end()
        .strip_prefix("[serve] listening on 127.0.0.1:")
        .and_then(|rest| rest.strip_suffix(&format!(" for the corpus {corpus}")))
        .map(|port| match port.parse::<u16>() {
            Ok(port) => port,
            Err(error) => panic!("flowmark serve printed the port {port:?}, which is not a u16: {error}"),
        })
        .unwrap_or_else(|| panic!("flowmark serve printed {line:?}, not its listening line"));
    let file: Value = serde_json::from_str(&std::fs::read_to_string(dir.join(".flowmark/server.json")).unwrap()).unwrap();
    let token = file["token"].as_str().expect("server.json has a token").to_owned();
    let dsn = format!("markdown://127.0.0.1:{port}/{corpus}?token={token}");
    let db = match markdown_model::connect(&dsn, 0, Config::default()).await {
        Ok(db) => db,
        Err(error) => panic!("connect: {error}"),
    };
    (Served { bin: bin.to_path_buf(), db, dir, corpus, port, token }, server)
}

/// Two JSON values are equal: numbers are equal if their values are equal (16 and 16.0).
pub fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(x, y)| same(x, y)),
        (Value::Object(x), Value::Object(y)) => x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w))),
        _ => a == b,
    }
}

/// The error the callback returns to roll back the transaction.
fn stop() -> Error {
    Error::Config("stop".into())
}

fn is_stop(error: &Error) -> bool {
    matches!(error, Error::Config(message) if message == "stop")
}

/// The orm code of the error of `r`, or null when it holds a value.
fn code_of<T>(r: polyspec_orm::Result<T>) -> Value {
    r.err().map_or(Value::Null, |e| Value::from(e.code().to_owned()))
}

/// The JSON of a bind of a statement: its value, as the other clients write it.
fn param_json(value: &polyspec_orm::Param) -> Value {
    use polyspec_orm::Param;
    match value {
        Param::Null => Value::Null,
        Param::Bool(b) => json!(b),
        Param::I64(n) => json!(n),
        Param::F64(x) => json!(x),
        Param::Str(s) => json!(s),
        Param::Bytes(b) => json!(b),
        Param::DateTime(t) => json!(t.to_string()),
        Param::Date(d) => json!(d.to_string()),
    }
}

/// An integer result value, which a client may hold as a number or as its text; an absent or null value is null.
fn integer(v: Option<Value>) -> Value {
    match v {
        Some(Value::String(text)) => match text.parse::<i64>() {
            Ok(number) => json!(number),
            Err(error) => panic!("invalid integer text: {text}: {error}"),
        },
        Some(other) => other,
        None => Value::Null,
    }
}

/// Installs tests/markdown/catalogs/<name>.dbs as the one document of the set of a new corpus and answers {"error": null},
/// or the code of its refusal, {"error": code}.
fn install_catalog(s: &Served, name: &str) -> Value {
    let scratch = Scratch(std::env::temp_dir().join(format!("orm-markdown-catalog-{}-{}", std::process::id(), unique())));
    let dir = scratch.0.join(name);
    std::fs::create_dir_all(dir.join("dbspec")).unwrap();
    std::fs::copy(conformance_dir().join(format!("catalogs/{name}.dbs")), dir.join(format!("dbspec/{name}.dbs"))).unwrap();
    std::fs::write(dir.join("dbspec/dbspec-set.json"), json!({ "schema": 1, "documents": [format!("{name}.dbs")] }).to_string()).unwrap();
    let install = Command::new(&s.bin).arg("install").arg(&dir).output().unwrap();
    if install.status.success() {
        return json!({ "error": null });
    }
    let out = format!("{}{}", String::from_utf8_lossy(&install.stdout), String::from_utf8_lossy(&install.stderr));
    let code = out
        .lines()
        .find_map(|line| line.strip_prefix("flowmark install: ")?.split_once(':').map(|(code, _)| code.to_owned()))
        .filter(|code| !code.is_empty() && code.bytes().all(|b| b.is_ascii_uppercase() || b == b'_'))
        .unwrap_or_else(|| panic!("flowmark install {}: {} without a refusal code\n{out}", dir.display(), install.status));
    json!({ "error": code })
}

/// Runs case `id` and returns the result value that the README defines. An error becomes the {"error": code} result for that code.
pub async fn run_case(id: &str, s: &Served) -> polyspec_orm::Result<Value> {
    let db = &s.db;
    Ok(match id {
        "insert_one" => {
            let m =
                People::new().connect(db).set_name("Ann").set_email(Some("ann@example.com".to_owned())).set_age(Some(30)).set_score("1.50")?.create().await?;
            json!({ "id": m.get_id()? })
        }
        "insert_rows" => {
            let bob = People::new().set_name("Bob").set_email(Some("bob@example.com".to_owned())).set_age(Some(25)).set_score("2.00")?;
            let cara = People::new().set_name("Cara").set_email(None::<String>).set_age(None::<i32>).set_score("0.50")?;
            json!(People::new().connect(db).creates(vec![bob, cara], 2).await?)
        }
        "insert_rows_tasks" => {
            let rows = vec![
                Tasks::new().set_owner("P1").set_title("write spec").set_points(3).set_due(Some("2026-10-01".to_string()))?,
                Tasks::new().set_owner("P1").set_title("review").set_points(5).set_due(None::<String>)?,
                Tasks::new().set_owner("P2").set_title("ship").set_points(8).set_due(Some("2026-10-05".to_string()))?,
            ];
            json!(Tasks::new().connect(db).creates(rows, 100).await?)
        }
        "insert_identity" => {
            let m = Logs::new().connect(db).set_task("T1").set_note("started").create().await?;
            json!({ "id": m.get_id()? })
        }
        "one" => People::new()
            .connect(db)
            .remove_all_columns()
            .add_column_name()
            .add_column_email()
            .add_column_age()
            .add_column_active()
            .add_column_score()
            .id("P1")
            .get()
            .await?
            .ok_or(polyspec_orm::Error::NoRows)?
            .to_array()?
            .plain()?,
        "one_no_rows" => People::new().connect(db).id("P9").get().await?.map(|m| m.to_array().and_then(|v| v.plain())).transpose()?.unwrap_or(Value::Null),
        "all" => People::new().connect(db).remove_all_columns().add_column_name().add_column_age().order_by_name_desc().gets().await?.to_array()?.plain()?,
        "count" => json!(Tasks::new().connect(db).owner("P1").get_count().await?),
        "group_count" => Tasks::new().connect(db).group_by_owner().order_by_owner_asc().gets_count().await?.to_array()?.plain()?,
        "group_count_no_rows" => Tasks::new().connect(db).owner("P9").group_by_owner().order_by_owner_asc().gets_count().await?.to_array()?.plain()?,
        "group_count_views" => {
            let rows = People::new().connect(db).group_by_active().group_by_age().order_by_age_desc().gets_count().await?;
            let first = match rows.iter().next() {
                Some(row) => json!({
                    "count": row.count(),
                    "active": row.value("active")?.to_json()?,
                    "age": row.value("age")?.to_json()?,
                    "unselected": row.value("name").err().map(|error| error.code().to_owned()),
                }),
                None => Value::Null,
            };
            let counts: Vec<i64> = rows.iter().map(|row| row.count()).collect();
            json!({ "length": rows.len(), "counts": counts, "rows": rows.to_array()?.plain()?, "first": first })
        }
        "group_count_i64" => Logs::new().connect(db).group_by_id().order_by_id_asc().gets_count().await?.to_array()?.plain()?,
        "collection_typed_key" => {
            let rows = Logs::new().connect(db).fetch_value(|row: &Logs| json!(row.get_note().unwrap())).gets().await?;
            let id = |row: Option<&Logs>| row.map(|row| row.get_id()).transpose();
            let keys: Vec<Value> = rows.keys().iter().map(|key| key.to_json()).collect();
            let mut values = Vec::new();
            for row in rows.models() {
                values.push(json!(row.get_id()?));
            }
            let mut entries = Vec::new();
            for (key, row) in rows.iter() {
                entries.push(json!([key.to_json(), row.get_id()?]));
            }
            json!({
                "length": rows.len(),
                "keys": keys,
                "values": values,
                "entries": entries,
                "first": id(rows.first())?,
                "get": id(rows.get(1))?,
                "get_text": id(rows.get("1"))?,
                "get_missing": id(rows.get(2))?,
                "has": rows.get(1).is_some(),
                "has_text": rows.get("1").is_some(),
                "fetched": rows.fetched_value(1),
                "fetched_text": rows.fetched_value("1"),
                "fetched_missing": rows.fetched_value(2),
                "array": rows.to_array()?.plain()?,
            })
        }
        "collection_key_name" => {
            let rows = People::new().connect(db).key_name_age().gets().await?;
            Value::Array(rows.keys().iter().map(|key| key.to_json()).collect())
        }
        "sum" => json!(Tasks::new().connect(db).sum_points().get_sum().await?),
        "avg" => json!(People::new().connect(db).avg_age().get_avg().await?),
        "paginate" => {
            let page = People::new().connect(db).remove_all_columns().add_column_name().order_by_name_asc().gets_page(2, 2).await?;
            json!({ "items": page.items.to_array()?.plain()?, "total_count": page.total_count, "total_pages": page.total_pages })
        }
        "join" => Tasks::new()
            .connect(db)
            .remove_all_columns()
            .add_column_title()
            .join_owner_with_id(People::new().remove_all_columns().add_column_name())
            .order_by_title_asc()
            .gets()
            .await?
            .to_array()?
            .plain()?,
        "relation_many" => People::new()
            .connect(db)
            .remove_all_columns()
            .add_column_name()
            .relations(Tasks::new().remove_all_columns().add_column_due().match_id_with_owner().order_by_title_asc())
            .id("P1")
            .get()
            .await?
            .ok_or(polyspec_orm::Error::NoRows)?
            .to_array()?
            .plain()?,
        "relation_one" => Tasks::new()
            .connect(db)
            .remove_all_columns()
            .add_column_title()
            .relation(People::new().remove_all_columns().add_column_name().match_owner_with_id())
            .id("T3")
            .get()
            .await?
            .ok_or(polyspec_orm::Error::NoRows)?
            .to_array()?
            .plain()?,
        "update" => {
            let mut m = People::new().connect(db).id("P2").get().await?.ok_or(polyspec_orm::Error::NoRows)?.set_age(Some(26));
            m.update(false).await?;
            People::new().connect(db).remove_all_columns().add_column_age().id("P2").get().await?.ok_or(polyspec_orm::Error::NoRows)?.to_array()?.plain()?
        }
        "update_optimistic_conflict" => {
            let stale = People::new().connect(db).id("P2").get().await?.ok_or(polyspec_orm::Error::NoRows)?;
            let mut fresh = People::new().connect(db).id("P2").get().await?.ok_or(polyspec_orm::Error::NoRows)?.set_name("Bobby");
            fresh.update(false).await?;
            let mut stale = stale.set_age(Some(27));
            stale.update(true).await?;
            Value::Null
        }
        "insert_on_duplicate" => {
            let m = People::new()
                .connect(db)
                .set_name("Ann B")
                .set_email(Some("ann@example.com".to_owned()))
                .duplication(People::new().set_name("Ann B"))
                .create()
                .await?;
            let read = People::new().connect(db).id("P1").get().await?.ok_or(polyspec_orm::Error::NoRows)?;
            json!({ "created": m.get_id()?, "name": read.get_name()? })
        }
        "delete" => {
            Tasks::new().connect(db).id("T2").get().await?.ok_or(polyspec_orm::Error::NoRows)?.delete(false).await?;
            json!(Tasks::new().connect(db).get_count().await?)
        }
        "delete_referenced" => {
            Tasks::new().connect(db).id("T1").get().await?.ok_or(polyspec_orm::Error::NoRows)?.delete(false).await?;
            Value::Null
        }
        "soft_delete" => {
            People::new().connect(db).id("P3").get().await?.ok_or(polyspec_orm::Error::NoRows)?.delete(false).await?;
            json!(People::new().connect(db).get_count().await?)
        }
        "restore" => {
            let m = People::new().connect(db).set_id("P3").restore().await?;
            let count = People::new().connect(db).get_count().await?;
            json!({ "id": m.get_id()?, "name": m.get_name()?, "count": count })
        }
        "transaction_commit" => {
            db.transaction(async || Logs::new().set_task("T3").set_note("committed").create().await.map(drop)).await?;
            json!(Logs::new().connect(db).get_count().await?)
        }
        "transaction_rollback" => {
            let ended: polyspec_orm::Result<()> = db
                .transaction(async || {
                    Logs::new().set_task("T3").set_note("rolled back").create().await?;
                    Err(stop())
                })
                .await;
            match ended {
                Err(error) if is_stop(&error) => assert!(is_stop(&error), "{error:?}"),
                other => return Err(Error::Config(format!("the transaction ended with {other:?}, not its callback's error"))),
            }
            json!(Logs::new().connect(db).get_count().await?)
        }
        "savepoint_rollback" => {
            db.transaction(async || {
                Logs::new().set_task("T3").set_note("outer").create().await?;
                let inner: polyspec_orm::Result<()> = db
                    .transaction(async || {
                        Logs::new().set_task("T3").set_note("inner").create().await?;
                        Err(stop())
                    })
                    .await;
                match inner {
                    Err(error) if is_stop(&error) => Ok(()),
                    other => Err(Error::Config(format!("the savepoint ended with {other:?}, not its callback's error"))),
                }
            })
            .await?;
            let rows = Logs::new().connect(db).order_by_id_asc().gets().await?;
            let notes: Vec<String> = rows.models().map(|m| m.get_note().map(str::to_owned)).collect::<polyspec_orm::Result<_>>()?;
            json!(notes)
        }
        "read_only_write" => {
            db.transaction(async || Logs::new().set_task("T3").set_note("read only").create().await.map(drop)).read_only().await?;
            Value::Null
        }
        "lock_update" => {
            db.transaction(async || {
                People::new().connect(db).remove_all_columns().id("P1").for_update().get().await?.ok_or(polyspec_orm::Error::NoRows)?.to_array()?.plain()
            })
            .await?
        }
        "lock_nowait" => {
            db.transaction(async || People::new().connect(db).id("P1").for_update_no_wait().get().await.map(drop)).await?;
            Value::Null
        }
        // The statement of a read, which the connection plans in SQLite's dialect (docs/spec/dialects.md), and its binds.
        "get_query" => {
            let statement = People::new().connect(db).get_query().await?;
            let binds: Vec<Value> = statement.binds.iter().map(param_json).collect();
            json!({ "sql": statement.sql, "binds": binds })
        }
        "isolation" => {
            db.transaction(async || Ok(())).isolation(Isolation::Serializable).await?;
            Value::Null
        }
        "write_conflict" => {
            let committed = db
                .transaction(async || {
                    let mut m = People::new().id("P1").get().await?.ok_or(polyspec_orm::Error::NoRows)?.set_name("Ann C");
                    m.update(false).await?;
                    // An edit outside the engine: changes a file the transaction writes before commit.
                    let path = s.dir.join("people.flowmark.md");
                    let text = std::fs::read_to_string(&path).map_err(|e| Error::Config(format!("{}: {e}", path.display())))?;
                    if !text.contains("Cara") {
                        return Err(Error::Config(format!("{} holds no Cara to edit:\n{text}", path.display())));
                    }
                    std::fs::write(&path, text.replacen("Cara", "Carol", 1)).map_err(|e| Error::Config(format!("{}: {e}", path.display())))
                })
                .await;
            let read = People::new().connect(db).id("P1").get().await?.ok_or(polyspec_orm::Error::NoRows)?;
            let code = committed.err().map(|error| error.code().to_owned()).unwrap_or_default();
            json!({ "error": code, "name": read.get_name()? })
        }
        // A transaction that reads P1 and writes its own name back, with retry options: the commit's code (null when it
        // commits) and how many times the callback ran. WRITE_CONFLICT is never retried (docs/spec/protocol.md section 5).
        "transaction_retry_commit" => {
            let runs = std::sync::atomic::AtomicU32::new(0);
            let committed = db
                .transaction(async || {
                    runs.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    let m = People::new().id("P1").get().await?.ok_or(polyspec_orm::Error::NoRows)?;
                    let name = m.get_name()?.to_owned();
                    m.set_name(&name).update(false).await.map(drop)
                })
                .retry(3)
                .await;
            let code = committed.err().map(|error| Value::from(error.code().to_owned())).unwrap_or(Value::Null);
            json!({ "error": code, "runs": runs.load(std::sync::atomic::Ordering::SeqCst) })
        }
        "connect_corpus_mismatch" => {
            markdown_model::connect(&s.dsn("other", &s.token), 0, Config::default()).await?.close().await;
            Value::Null
        }
        "connect_token_mismatch" => {
            markdown_model::connect(&s.dsn(&s.corpus, &"0".repeat(32)), 0, Config::default()).await?.close().await;
            Value::Null
        }
        // NULL sorts before every value ascending and after every value descending.
        "order_nulls" => json!({
            "asc": People::new().connect(db).remove_all_columns().add_column_age().order_by_age_asc().gets().await?.to_array()?.plain()?,
            "desc": People::new().connect(db).remove_all_columns().add_column_age().order_by_age_desc().gets().await?.to_array()?.plain()?,
        }),
        // orderByRandom is supported and not seeded, so the case answers the keys sorted.
        "order_random" => {
            let rows = People::new().connect(db).remove_all_columns().order_by_random().gets().await?;
            let mut keys = rows.models().map(|m| m.get_id().map(str::to_owned)).collect::<polyspec_orm::Result<Vec<String>>>()?;
            keys.sort();
            json!(keys)
        }
        // The key t3 equals T3 without regard to case: a plain insert and an on_duplicate insert are DUPLICATE_KEY, and T3
        // keeps its key and its row.
        "primary_key_case" => {
            let duplicate = code_of(Tasks::new().connect(db).set_id("t3").set_owner("P2").set_title("dup").set_points(1).create().await);
            let upsert = code_of(
                Tasks::new()
                    .connect(db)
                    .set_id("t3")
                    .set_owner("P2")
                    .set_title("ship it")
                    .set_points(8)
                    .duplication(Tasks::new().set_title("ship it"))
                    .create()
                    .await,
            );
            let met = Tasks::new()
                .connect(db)
                .remove_all_columns()
                .add_column_title()
                .id("T3")
                .get()
                .await?
                .ok_or(polyspec_orm::Error::NoRows)?
                .to_array()?
                .plain()?;
            json!({ "duplicate": duplicate, "upsert": upsert, "met": met, "count": Tasks::new().connect(db).get_count().await? })
        }
        // Two columns compared with a list of value groups, IN and NOT IN.
        "tuple_in" => {
            let pairs = || vec![("T1".to_owned(), "P1".to_owned()), ("T3".to_owned(), "P1".to_owned())];
            json!({
                "in": Tasks::new().connect(db).remove_all_columns().tuple_id_with_owner(pairs()).order_by_id_asc().gets().await?.to_array()?.plain()?,
                "not_in": Tasks::new().connect(db).remove_all_columns().ne_tuple_id_with_owner(pairs()).order_by_id_asc().gets().await?.to_array()?.plain()?,
            })
        }
        // The sum of each person's task points as a scalar Sub aggregate, and the owners of a task through an IN subquery
        //.
        "subquery_aggregate" => {
            let rows = People::new()
                .connect(db)
                .remove_all_columns()
                .add_column_task_points(|p: &People| Tasks::new().sum_points().owner_eq_id(p))
                .order_by_id_asc()
                .gets()
                .await?;
            let mut sums = Vec::new();
            for m in rows.models() {
                sums.push(json!([m.get_id()?, integer(m.get_task_points()?)]));
            }
            let owners =
                People::new().connect(db).remove_all_columns().id(Tasks::new().add_column_owner()).order_by_id_asc().gets().await?.to_array()?.plain()?;
            json!({ "sums": sums, "owners": owners })
        }
        // The title of each person's first task, a column subquery with limit 1 and an order by the primary key; without
        // the limit it is IR_INVALID.
        "scalar_column_subquery" => {
            let rows = People::new()
                .connect(db)
                .remove_all_columns()
                .add_column_first_task(|p: &People| Tasks::new().remove_all_columns().add_column_title().owner_eq_id(p).order_by_id_asc().limit(0, 1))
                .order_by_id_asc()
                .gets()
                .await?;
            let mut first = Vec::new();
            for m in rows.models() {
                first.push(json!([m.get_id()?, m.get_first_task()?]));
            }
            let unlimited = code_of(
                People::new()
                    .connect(db)
                    .remove_all_columns()
                    .add_column_first_task(|p: &People| Tasks::new().remove_all_columns().add_column_title().owner_eq_id(p).order_by_id_asc())
                    .order_by_id_asc()
                    .gets()
                    .await,
            );
            json!({ "first": first, "unlimited": unlimited })
        }
        // varchar with varchar meet; i32 with varchar do not and are OPERATOR_NOT_ALLOWED.
        "column_pairs" => {
            let p = People::new();
            let meet = Tasks::new().connect(db).join_owner_with_id(p.clone()).title_ne_name(&p).get_count().await?;
            let q = People::new();
            let refused = code_of(Tasks::new().connect(db).join_owner_with_id(q.clone()).points_eq_name(&q).get_count().await);
            json!({ "meet": meet, "refused": refused })
        }
        // Lk: A-Z and a-z without regard to case, % literal.
        "contains" => json!({
            "fold": People::new().connect(db).remove_all_columns().lk_name("ANN").order_by_id_asc().gets().await?.to_array()?.plain()?,
            "literal": People::new().connect(db).remove_all_columns().lk_name("%").order_by_id_asc().gets().await?.to_array()?.plain()?,
        }),
        // Lb: compared by code point.
        "contains_binary" => json!({
            "exact": People::new().connect(db).remove_all_columns().lb_name("Ann").order_by_id_asc().gets().await?.to_array()?.plain()?,
            "folded": People::new().connect(db).remove_all_columns().lb_name("ann").order_by_id_asc().gets().await?.to_array()?.plain()?,
        }),
        // The default now of joined, a datetime(0), holds no fraction, and a relative time function past 9999-12-31 is
        // NULL and matches no row.
        "now_truncated" => {
            use polyspec_orm::chrono::Timelike;
            let joined = People::new().connect(db).id("P1").get().await?.ok_or(polyspec_orm::Error::NoRows)?.get_joined()?;
            let far = || polyspec_orm::seconds_later(1000000000000000);
            json!({
                "fraction": joined.nanosecond(),
                "out_of_range": [People::new().connect(db).and_gt_joined(far()).get_count().await?, People::new().connect(db).and_le_joined(far()).get_count().await?],
            })
        }
        // A read through the column of the index ix_tasks_owner, which the corpus derives in memory.
        "index_read" => Tasks::new().connect(db).remove_all_columns().owner("P2").gets().await?.to_array()?.plain()?,
        // A read with an index hint, which the corpus derives in memory, so the read answers its rows.
        "force_index" => Tasks::new().connect(db).force_index_ix_tasks_owner().owner("P1").gets().await?.to_array()?.plain()?,
        // A heading of another table in tasks.flowmark.md is format.block: a read of tasks fails CONSTRAINT naming the
        // file, and reads again once the file is restored.
        "unavailable_table" => {
            let path = s.dir.join("tasks.flowmark.md");
            let io = |e: std::io::Error| Error::Config(format!("{}: {e}", path.display()));
            let text = std::fs::read(&path).map_err(io)?;
            let mut broken_text = text.clone();
            broken_text.extend_from_slice(b"\n## people row P1\n");
            std::fs::write(&path, &broken_text).map_err(io)?;
            let broken = Tasks::new().connect(db).get_count().await;
            std::fs::write(&path, &text).map_err(io)?;
            let names_file = broken.as_ref().is_err_and(|e| e.to_string().contains("tasks.flowmark.md"));
            json!({ "broken": code_of(broken), "names_file": names_file, "restored": Tasks::new().connect(db).get_count().await? })
        }
        // codec_insert writes a base64-encoded value to an explicit column.
        "codec_insert" => {
            let row = CodecRows::new().set_id("C1").set_payload(StyledValue::Value("first encoded value".into()))?;
            let created = row.connect(db).create().await?;
            json!({ "id": created.get_id()? })
        }
        // codec_default_select asks for a select-explicit getter without selecting it.
        "codec_default_select" => {
            let row = CodecRows::new().connect(db).id("C1").get().await?.ok_or(Error::NoRows)?;
            let _payload = row.get_payload()?;
            Value::Null
        }
        // codec_explicit_select reads the selected column through its base64 codec.
        "codec_explicit_select" => {
            let row = CodecRows::new().connect(db).remove_all_columns().add_column_payload().id("C1").get().await?.ok_or(Error::NoRows)?;
            match row.get_payload()? {
                StyledValue::Value(value) => json!(value),
                StyledValue::SqlNull => json!("sql-null"),
            }
        }
        // codec_update changes the encoded value and reads back the decoded text.
        "codec_update" => {
            let row = CodecRows::new().connect(db).remove_all_columns().add_column_payload().id("C1").get().await?.ok_or(Error::NoRows)?;
            row.set_payload(StyledValue::Value("updated encoded value".into()))?.update(false).await?;
            let read = CodecRows::new().connect(db).remove_all_columns().add_column_payload().id("C1").get().await?.ok_or(Error::NoRows)?;
            match read.get_payload()? {
                StyledValue::Value(value) => json!(value),
                StyledValue::SqlNull => json!("sql-null"),
            }
        }
        // select_explicit_insert_omitted inserts a row without the explicit column.
        "select_explicit_insert_omitted" => {
            let created = CodecRows::new().connect(db).set_id("C2").create().await?;
            json!({ "id": created.get_id()? })
        }
        // select_explicit_read_null includes the omitted SQL NULL column in the read.
        "select_explicit_read_null" => {
            let row = CodecRows::new().connect(db).remove_all_columns().add_column_payload().id("C2").get().await?.ok_or(Error::NoRows)?;
            match row.get_payload()? {
                StyledValue::SqlNull => json!("sql-null"),
                StyledValue::Value(_) => json!("value"),
            }
        }
        // install_aes installs a catalog with an aes column and its key version column, as docs/spec/dialects.md has it.
        "install_aes" => install_catalog(s, "aes"),
        // install_audit installs a catalog with an audit setting, its record table and its history table, as docs/spec/dialects.md has it.
        "install_audit" => install_catalog(s, "audit"),
        other => unreachable!("case {other} is not in CASES"),
    })
}

/// The corpus name of a recipe case; each case has a directory of its own.
pub const CASE_CORPUS: &str = "recipe";

/// A corpus of a recipe case and its server, which stops when this drops, before the directory goes.
pub struct CaseCorpus {
    pub dsn: String,
    /// The directory of the corpus.
    pub dir: PathBuf,
    _server: Server,
    _scratch: Scratch,
}

/// Installs the documents and the external documents of the dbspec set at `set` as a new corpus, or, with no set, a corpus with
/// no table, and starts the flowmark of FLOWMARK on it. A corpus of a test is disposable, as a test database server is: a commit
/// does not wait for the disk.
pub async fn case_corpus(set: Option<&Path>) -> CaseCorpus {
    let bin = std::env::var("FLOWMARK").expect("FLOWMARK is required; make orm-install-flowmark builds the version that tests/markdown/flowmark.version pins");
    static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let number = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let scratch = Scratch(std::env::temp_dir().join(format!("orm-corpus-{}-{number}", std::process::id())));
    let dir = scratch.0.join(CASE_CORPUS);
    let dbspec = dir.join("dbspec");
    std::fs::create_dir_all(&dbspec).unwrap();
    if let Some(set) = set {
        let text = std::fs::read_to_string(set).unwrap();
        std::fs::write(dbspec.join(set.file_name().unwrap()), &text).unwrap();
        let parsed: Value = serde_json::from_str(&text).unwrap();
        let named = parsed["documents"].as_array().into_iter().chain(parsed["external"].as_array()).flatten().filter_map(Value::as_str);
        for document in named {
            std::fs::copy(set.parent().unwrap().join(document), dbspec.join(document)).unwrap();
        }
    }
    let install = Command::new(&bin).arg("install").arg(&dir).output().unwrap();
    assert!(install.status.success(), "flowmark install: {}{}", String::from_utf8_lossy(&install.stdout), String::from_utf8_lossy(&install.stderr));
    let mut child = Command::new(&bin)
        .arg("serve")
        .arg(&dir)
        .args(["--port", "0", "--synchronous", "off", "--tx-idle-ms", "600000"])
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    let stdout = child.stdout.take().unwrap();
    let server = Server(child);
    let line = tokio::task::spawn_blocking(move || {
        let mut line = String::new();
        std::io::BufRead::read_line(&mut std::io::BufReader::new(stdout), &mut line).unwrap();
        line
    })
    .await
    .unwrap();
    let port = line
        .trim_end()
        .strip_prefix("[serve] listening on 127.0.0.1:")
        .and_then(|rest| rest.split(' ').next())
        .unwrap_or_else(|| panic!("flowmark serve printed {line:?}, not its listening line"))
        .to_owned();
    let file: Value = serde_json::from_str(&std::fs::read_to_string(dir.join(".flowmark/server.json")).unwrap()).unwrap();
    let token = file["token"].as_str().expect("server.json has a token").to_owned();
    CaseCorpus { dsn: format!("markdown://127.0.0.1:{port}/{CASE_CORPUS}?token={token}"), dir, _server: server, _scratch: scratch }
}
